import test from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';
import sharp from 'sharp';
import { randomBytes } from 'node:crypto';
import { mkdtempSync, rmSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createApp } from '../server/app.js';
import { createContentStore } from '../server/models/contentStore.js';
import { createMediaStore } from '../server/models/mediaStore.js';
import mockCmsData from '../src/data/mockCmsData.js';

const origin = 'http://127.0.0.1:5173';

/** Isolates uploaded files and SQLite from the real site. */
function fixture(t, contactMailer = { ready: false }) {
  const directory = mkdtempSync(join(tmpdir(), 'wise-media-'));
  const store = createContentStore({ databasePath: ':memory:', seed: mockCmsData });
  t.after(() => { store.close(); rmSync(directory, { recursive: true, force: true }); });
  return { app: createApp({ contentStore: store, mediaStore: createMediaStore(directory), contactMailer }), directory };
}

test('authenticated uploads validate bytes, produce WebP, and publish multiple event images', async t => {
  const { app, directory } = fixture(t);
  const password = randomBytes(24).toString('hex');
  await app.locals.adminStore.provision('media-admin', password);
  const agent = request.agent(app);
  const signed = await agent.post('/api/admin/login').set('Origin', origin).send({ username: 'media-admin', password });
  const csrf = signed.body.csrfToken;
  await request(app).post('/api/admin/uploads').set('Origin', origin).expect(401);
  const png = await sharp({ create: { width: 16, height: 16, channels: 3, background: '#15803d' } }).png().toBuffer();
  await agent.post('/api/admin/uploads').set('Origin', origin).attach('images', png, 'valid.png').expect(403);
  await agent.post('/api/admin/uploads').set('Origin', origin).set('X-CSRF-Token', csrf).attach('images', Buffer.from('not a PNG'), { filename: 'fake.png', contentType: 'image/png' }).expect(400);
  await agent.post('/api/admin/uploads').set('Origin', origin).set('X-CSRF-Token', csrf).attach('images', Buffer.from('<svg></svg>'), { filename: 'vector.svg', contentType: 'image/svg+xml' }).expect(400);
  await agent.post('/api/admin/uploads').set('Origin', origin).set('X-CSRF-Token', csrf).attach('images', Buffer.alloc(5 * 1024 * 1024 + 1), { filename: 'oversized.png', contentType: 'image/png' }).expect(413);
  assert.equal(readdirSync(directory).length, 0);
  const uploaded = await agent.post('/api/admin/uploads').set('Origin', origin).set('X-CSRF-Token', csrf).attach('images', png, 'one.png').attach('images', png, 'two.png').expect(201);
  assert.equal(uploaded.body.images.length, 2);
  const image = await request(app).get(uploaded.body.images[0].src).expect(200);
  assert.match(image.headers['content-type'], /image\/webp/);
  assert.equal((await sharp(image.body).metadata()).format, 'webp');
  const editable = (await agent.get('/api/admin/content')).body;
  editable.content.site.logo = { src: uploaded.body.images[0].src, alt: 'Uploaded logo' };
  editable.content.events.items.push({ id: 'test-event', title: 'Community event', description: 'An event description.', date: '2026-10-10', images: uploaded.body.images.map(item => ({ ...item, alt: 'Community activity' })) });
  await agent.put('/api/admin/content').set('Origin', origin).set('X-CSRF-Token', csrf).send({ content: editable.content, version: editable.version }).expect(200);
  const published = (await request(app).get('/api/content')).body;
  assert.equal(published.events.items[0].images.length, 2);
  assert.equal(published.site.logo.src, uploaded.body.images[0].src);
});

test('contact delivery validates origin and input, traps spam, and handles failures honestly', async t => {
  const sent = [];
  const { app } = fixture(t, { ready: true, async send(message) { sent.push(message); } });
  const message = { name: 'Visitor', email: 'visitor@example.com', subject: 'Partnership', message: 'Please contact me.', website: '' };
  await request(app).post('/api/contact').send(message).expect(403);
  await request(app).post('/api/contact').set('Origin', origin).send({ ...message, email: 'invalid' }).expect(400);
  await request(app).post('/api/contact').set('Origin', origin).send({ ...message, subject: 'Header\r\nBcc: someone@example.com' }).expect(400);
  await request(app).post('/api/contact').set('Origin', origin).send({ ...message, website: 'spam' }).expect(200);
  assert.equal(sent.length, 0);
  await request(app).post('/api/contact').set('Origin', origin).send(message).expect(200);
  assert.equal(sent.length, 1);
  app.locals.contactMailer = { ready: true, async send() { throw new Error('private SMTP credentials'); } };
  const failed = await request(app).post('/api/contact').set('Origin', origin).send(message).expect(502);
  assert.ok(!JSON.stringify(failed.body).includes('credentials'));
  await request(app).post('/api/contact').set('Origin', origin).send(message).expect(429);
});

test('unconfigured SMTP reports unavailable instead of successful delivery', async t => {
  const { app } = fixture(t);
  await request(app).post('/api/contact').set('Origin', origin).send({ name: 'Visitor', email: 'visitor@example.com', subject: 'Inquiry', message: 'Hello' }).expect(503);
});